ALLOWED = {'value', 'unit', 'value_stored', 'unit_stored', 'property', 'temperature_K', 'temperature_basis', 'phases',
           'structure', 'overall_composition', 'overall_composition_basis', 'duplicate_of', 'uncertainty'}
PROPERTIES = {'INVARIANT_TEMPERATURE', 'TRANSITION_TEMPERATURE', 'HM_FORM', 'PHASE_COMPOSITION', 'LATTICE_A', 'LATTICE_B',
              'LATTICE_C', 'LATTICE_ALPHA', 'LATTICE_BETA', 'LATTICE_GAMMA', 'LATTICE_C_A', 'LATTICE_V', 'LATTICE_V_ATOM',
              'LATTICE_UNSPECIFIED_AXIS', 'CPM', 'CPM_EXPRESSION_TERM', 'HM_MIX', 'SM', 'SM_FORM', 'SM_MIX', 'SM_FUSION',
              'SM_EXCESS', 'SM_INCREMENT', 'SM_CONTRIBUTION', 'ENTROPY', 'HEAT_CONTENT', 'GIBBS_ENERGY', 'GM_FORM', 'GM_MIX',
              'EMF', 'TRANSITION_ENTHALPY', 'MOLAR_VOLUME', 'VOLUME', 'PARTIAL_ENTHALPY', 'CHEMICAL_POTENTIAL', 'ACTIVITY', 'OTHER'}
PRESERVED = ['value', 'unit', 'value_stored', 'unit_stored', 'uncertainty', 'pressure_Pa', 'overall_composition',
             'phases', 'property', 'paper', 'pid', 'locator', 'temperature_K', 'structure', 'merged_ids']


def fixtures(patches=PATCHES):
    rows = [dict(copy.deepcopy(p['before']), id=p['record_id'], flags={'espei_ready': True, 'espei_certified': True,
                                                                         'extraction_accepted': True}) for p in patches]
    have = {r['id'] for r in rows}
    for p in patches:   # the kept record of each duplicate pair, itself unpatched
        k = p['after'].get('duplicate_of')
        if k and k not in have:
            rows.append(dict(copy.deepcopy(p['before']), id=k, flags={'extraction_accepted': True})); have.add(k)
    return rows


class TableDefects(unittest.TestCase):
    def test_schema_and_scope(self):
        self.assertEqual(len(PATCHES), EXPECTED['patches'])
        self.assertEqual(sum('duplicate_of' in p['after'] for p in PATCHES), EXPECTED['duplicates'])
        self.assertEqual(len({p['record_id'] for p in PATCHES}), len(PATCHES))
        for p in PATCHES:
            self.assertNotIn('flags', p['before'])
            self.assertNotIn('cited_sources', p['before'])   # rewritten later in the export
            self.assertEqual(p['evidence']['report_id'], 'ORCHID-TD-20261028-v1')
            self.assertEqual(p['visual_check']['verdict'], 'confirmed')
            self.assertRegex(p['visual_check']['image_sha256'] or '', '^[0-9a-f]{64}$')
            self.assertLessEqual(len(p['evidence'].get('printed') or ''), 500)
            self.assertTrue(set(p['after']) <= ALLOWED, p['record_id'])
            for k in p['after']:
                self.assertIn(k, p['before'], 'every changed field is guarded: ' + k)
            if 'property' in p['after']:
                self.assertIn(p['after']['property'], PROPERTIES)
            if 'temperature_basis' in p['after']:
                self.assertIn(p['after']['temperature_basis'], {'printed', 'assumed_standard_298K', 'quantity_label'})

    def test_no_overlap_with_other_patch_files(self):
        # the 13 per-formula aliases of the per-atom file are exempt (PI decision; 6 of them carry TC-batch corrections)
        peratom_aliases = {p['record_id'] for p in json.loads((TOOLS / 'table_defects_corrections_20261028_peratom.json').read_text())}
        mine = ({p['record_id'] for p in PATCHES} | set(FLAG_IDS)) - peratom_aliases
        for f in glob.glob(str(TOOLS / '*corrections_2026*.json')):
            if Path(f).name.startswith(('table_defects_corrections_20261028', 'codex_y1')):
                continue  # later rounds (Codex Y10/Y11, 28 Oct) act on TD-targeted records by design: blocked duplicates
            other = json.loads(Path(f).read_text())
            if isinstance(other, list):
                self.assertFalse(mine & {p.get('record_id') for p in other}, f)

    def test_unit_conversions_exact(self):
        for p in PATCHES:
            a = p['after']
            if a.get('unit') == 'Å' and a.get('unit_stored', p['before'].get('unit_stored')) == 'nm' and 'value' in a:
                vs = a.get('value_stored', p['before'].get('value_stored'))
                self.assertAlmostEqual(a['value'], 10 * vs, places=6, msg=p['record_id'])

    def test_apply_changes_only_patched_fields(self):
        rows = fixtures(); before = copy.deepcopy(rows)
        h.apply(rows, PATCHES, **KW)
        byid = {r['id']: r for r in rows}; old = {r['id']: r for r in before}
        for p in PATCHES:
            r = byid[p['record_id']]
            for k, v in p['after'].items():
                self.assertEqual(r[k], v)
            for k in PRESERVED:
                if k not in p['after']:
                    self.assertEqual(old[p['record_id']].get(k), r.get(k), k)
            self.assertFalse(r['flags']['espei_ready']); self.assertTrue(r['flags']['extraction_accepted'])
            self.assertTrue(any(c['gate'] == 'TD20261028' for c in r['corrections']))
        patched = {p['record_id'] for p in PATCHES}
        for i, r in old.items():
            if i not in patched:
                self.assertEqual(byid[i], r)   # kept records untouched
        aliases = {p['record_id'] for p in PATCHES if 'duplicate_of' in p['after']}
        for p in PATCHES:
            self.assertNotIn(p['after'].get('duplicate_of'), aliases)   # no chains

    def test_replay_idempotent(self):
        rows = fixtures(); h.apply(rows, PATCHES, **KW); once = copy.deepcopy(rows)
        again = h.apply(rows, PATCHES, **KW)
        self.assertEqual(rows, once); self.assertEqual(again['applied'], [])

    def test_changed_guard_aborts_whole_batch(self):
        rows = fixtures(); rows[0]['value'] = 'changed upstream'; before = copy.deepcopy(rows)
        with self.assertRaises(ValueError):
            h.apply(rows, PATCHES, **KW)
        self.assertEqual(rows, before)

    def test_ledger_flags(self):
        visual = G.load_visual()
        for rid, codes in FLAG_IDS.items():
            chk = visual.get('flag:' + rid)
            self.assertIsNotNone(chk, rid)
            self.assertEqual(chk.get('verdict'), 'confirmed'); self.assertTrue(chk.get('image_sha256'))
            got = {(f['code'], f['effect']) for f in chk['flags']}
            for c in codes:
                self.assertIn(tuple(c), got, rid)
        dups = {p['record_id']: p['after']['duplicate_of'] for p in PATCHES if 'duplicate_of' in p['after']}
        for rid, kept in dups.items():
            chk = visual.get('flag:' + rid)
            self.assertIn(kept, [x for f in chk['flags'] if f['code'] == 'duplicate_source_row' for x in f.get('related_records', [])])

    def test_not_accepted_flag_demotes_without_value_change(self):
        r = {'id': 'x', 'value': 496.7, 'temperature_K': 298.15,
             'flags': {'espei_ready': True, 'espei_certified': True, 'extraction_accepted': True}}
        old = copy.deepcopy(r)
        G.fail(r, 'page', 'value_not_the_stated_property', 'not_accepted', 'lattice parameter read as an enthalpy')
        self.assertFalse(r['flags']['extraction_accepted']); self.assertFalse(r['flags']['espei_ready'])
        self.assertEqual((r['value'], r['temperature_K']), (old['value'], old['temperature_K']))

    def test_exporter_applies_the_batch(self):
        src = (TOOLS / 'export_literature_data.py').read_text()
        self.assertIn('table_defects_corrections_20261028.json', src)
        self.assertIn('ORCHID-TD-20261028-v1', src)
        self.assertLess(src.index('known_issues_corrections_20261027.json'), src.index('table_defects_corrections_20261028.json'))


PERATOM = json.loads((TOOLS / 'table_defects_corrections_20261028_peratom.json').read_text())


class TableDefectsPerAtom(unittest.TestCase):
    def test_peratom_schema(self):
        self.assertEqual(len(PERATOM), 13)
        main_ids = {p['record_id'] for p in PATCHES}
        for p in PERATOM:
            self.assertEqual(set(p['after']), {'duplicate_of'})
            self.assertNotIn('flags', p['before']); self.assertNotIn('cited_sources', p['before'])
            self.assertIn('duplicate_of', p['before']); self.assertIsNone(p['before']['duplicate_of'])
            self.assertNotIn(p['record_id'], main_ids)            # alias not patched by the main file
            self.assertNotIn(p['after']['duplicate_of'], main_ids)  # kept per-atom record no longer an alias
            self.assertEqual(p['evidence']['report_id'], 'ORCHID-TD-20261028-v1')

    def test_peratom_apply_and_replay(self):
        rows = [dict(copy.deepcopy(p['before']), id=p['record_id'], flags={'espei_ready': True, 'extraction_accepted': True}) for p in PERATOM]
        h.apply(rows, PERATOM, **KW); once = copy.deepcopy(rows)
        for r, p in zip(rows, PERATOM):
            self.assertEqual(r['duplicate_of'], p['after']['duplicate_of']); self.assertFalse(r['flags']['espei_ready'])
        self.assertEqual(h.apply(rows, PERATOM, **KW)['applied'], []); self.assertEqual(rows, once)

    def test_exporter_applies_peratom_after_main(self):
        src = (TOOLS / 'export_literature_data.py').read_text()
        self.assertLess(src.index('table_defects_corrections_20261028.json'), src.index('table_defects_corrections_20261028_peratom.json'))


if __name__ == '__main__':
    unittest.main()
